#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int total;
    cin >> total;
    if (total >= 100) {
        cout << 0 << "\n";
    } else {
        vector<int> A(total + 1), B(total + 1), C(total + 1), D(total + 1), E(total + 1);
        for (int i = 1; i <= total; i++) {
            cin >> A[i] >> B[i] >> C[i] >> D[i] >> E[i];
        }
        unordered_set<int> excluded;
        for (int i = 1; i <= total; i++) {
            for (int j = 1; j <= total; j++) {
                if (j == i) continue;
                for (int k = 1; k <= total; k++) {
                    if (k == i || k == j) continue;
                    long long ax = A[j] - A[i], bx = B[j] - B[i], cx = C[j] - C[i], dx = D[j] - D[i], ex = E[j] - E[i];
                    long long ay = A[k] - A[i], by = B[k] - B[i], cy = C[k] - C[i], dy = D[k] - D[i], ey = E[k] - E[i];
                    double dotProduct = ax * ay + bx * by + cx * cy + dx * dy + ex * ey;
                    long long mag1 = ax * ax + bx * bx + cx * cx + dx * dx + ex * ex;
                    long long mag2 = ay * ay + by * by + cy * cy + dy * dy + ey * ey;
                    if (mag1 == 0 || mag2 == 0) continue; // avoid division by zero
                    double cosine = dotProduct / (sqrt((double)mag1) * sqrt((double)mag2));
                    double angle = acos(cosine) * 180.0 / M_PI;
                    if (angle + 1e-9 < 90.0) {
                        excluded.insert(i);
                        break; // no need to check further for this i
                    }
                }
                if (excluded.count(i)) break; // move to next i
            }
        }
        cout << total - (int)excluded.size() << "\n";
        for (int i = 1; i <= total; i++) {
            if (!excluded.count(i)) cout << i << "\n";
        }
    }
    return 0;
}
